# Имена титанов (titan_<имя>) — из titans.py (задача 16): там одна строка на титана со всеми языками
for _lang, _words in TRANSLATIONS.items():
    _words.update(titans.translation_keys(_lang))

# Языки окна программы: код → название на родном языке, в порядке списка выбора.
# Код уходит боту в HEROWARS_LANG: по нему бот берёт картинки кнопок игры из assets/<код>/
LANGUAGES = {
    "RU": "Русский",
    "EN": "English",
    "UK": "Українська",
    "KK": "Қазақша",
    "DE": "Deutsch",
    "ES": "Español",
    "FR": "Français",
    "PL": "Polski",
    "PT": "Português",
    "TR": "Türkçe",
    "ZH": "中文",
    "KO": "한국어",
    "JA": "日本語",
}

def get_text(lang, key):
    return TRANSLATIONS.get(lang, TRANSLATIONS["RU"]).get(key, key)